instance.peoplecode_text:
/****************************************************************************************************************************************

OU - Jared Norris

Demo of Oracle JET


Plan:

	1. Define and Load Banner
	2. Map Navigation
	3. Page Design
	4. Sections
	5. Rows
	6. Columns
	7. Footer

****************************************************************************************************************************************/
import OU_JET_PACK:Model:PageDesign;
import OU_JET_PACK:Storage:DesignRepository;
import OU_JET_PACK:Security:AccessCheck;
import OU_JET_PACK:Render:PageRenderer;
import OU_JET_PACK:Layout:ComponentRegistry;
import OU_JET_PACK:Model:PageCol;

Function IScript_JETLandingPage()

   Local string &designId, &siteBase, &bodyHtml;
   Local OU_JET_PACK:Security:AccessCheck &access = create OU_JET_PACK:Security:AccessCheck();
   Local OU_JET_PACK:Storage:DesignRepository &repo = create OU_JET_PACK:Storage:DesignRepository();
   Local OU_JET_PACK:Render:PageRenderer &renderer = create OU_JET_PACK:Render:PageRenderer();
   Local OU_JET_PACK:Layout:ComponentRegistry &registry = create OU_JET_PACK:Layout:ComponentRegistry();
   Local OU_JET_PACK:Model:PageDesign &design;
   Local array of string &neededModules = CreateArrayRept("", 0);
   Local integer &r2, &c2;
   Local boolean &needsJet = False;
   Local boolean &needsCollapsible = False;

   If Not &access.IsAuthorizedViewer() Then
      %Response.SetContentType("text/html");
      %Response.WriteLine("Not authorized.");
      Return;
   End-If;

   &siteBase = "/cs/" | %DbName | "/oraclejet";
   &designId = %Request.GetParameter("Design");

   &design = &repo.Load(&designId);
   If &design.IsNew Then
      %Response.WriteLine("Design not found.");
      Return;
   End-If;

   For &r2 = 1 To &design.Rows.Len
      For &c2 = 1 To &design.Rows [&r2].Cols.Len
         Local OU_JET_PACK:Model:PageCol &pc = &design.Rows [&r2].Cols [&c2];
         If &pc.ContentType = "COMPONENT" And
               &registry.IsSupported(&pc.ComponentTag) Then
            &needsJet = True;
            &neededModules.Push(&registry.GetRequireModule(&pc.ComponentTag));
         End-If;
         If &pc.ContentType = "COLLAPSIBLE" Then
            &needsJet = True;
            &needsCollapsible = True;
         End-If;
      End-For;
   End-For;

   &bodyHtml = &renderer.Render(&design);

   %Response.WriteLine("<!DOCTYPE html><html><head>");
   %Response.WriteLine("<link rel='stylesheet' href='" | &siteBase | "/css/libs/oj/14.1.1/redwood/oj-redwood-min.css'/>");
   %Response.WriteLine("<style>");
   %Response.WriteLine("body{margin:0;font-family:Arial,sans-serif;}");
   %Response.WriteLine(".jet-pg-row{width:100%;}");
   %Response.WriteLine(".jet-pg-col{padding:24px;box-sizing:border-box;}");
   %Response.WriteLine(".jet-pg-img{max-width:100%;display:block;}");
   %Response.WriteLine("</style>");

   If &needsJet Then
      %Response.WriteLine("<script src='" | &siteBase | "/js/libs/require/require-debug.js'></script>");
      %Response.WriteLine("<script>");
      %Response.WriteLine("requirejs.config({baseUrl:'" | &siteBase | "/js/libs',paths:{");
      %Response.WriteLine("'ojs':'oj/14.1.1/min','ojL10n':'oj/14.1.1/ojL10n','ojtranslations':'oj/14.1.1/resources',");
      %Response.WriteLine("'jquery':'jquery/jquery-3.6.1.min','jqueryui-amd':'jquery/jqueryui-amd-1.13.2.min',");
      %Response.WriteLine("'knockout':'knockout/knockout-3.5.1','@oracle/oraclejet-preact':'oraclejet-preact/amd',");
      %Response.WriteLine("'hammerjs':'hammer/hammer-2.0.8','ojdnd':'dnd-polyfill/dnd-polyfill-1.0.2','signals':'js-signals/signals',");
      %Response.WriteLine("'preact':'preact/dist/preact.umd','preact/hooks':'preact/hooks/dist/hooks.umd',");
      %Response.WriteLine("'preact/compat':'preact/compat/dist/compat.umd','preact/jsx-runtime':'preact/jsx-runtime/dist/jsxRuntime.umd'");
      %Response.WriteLine("}}); ");

      Local array of string &mods = &registry.GetAllRequireModules();
      Local string &modList;
      Local integer &m;

      &modList = "'ojs/ojcore'";
      For &m = 1 To &mods.Len
         &modList = &modList | ",'" | &mods [&m] | "'";
      End-For;

      If &needsCollapsible Then
         &mods.Push("ojs/ojcollapsible");
      End-If;

      %Response.WriteLine("require([" | &modList | "], function() {});");

      %Response.WriteLine("</script>");
   End-If;

   If &renderer.NeedsStructuredWidgetAssets(&design) Then
      %Response.WriteLine("<style>");
      %Response.WriteLine(".jet-flipcard{perspective:1000px;cursor:pointer;min-height:180px;}");
      %Response.WriteLine(".jet-flipcard-inner{position:relative;width:100%;height:100%;min-height:180px;transition:transform 0.6s;transform-style:preserve-3d;}");
      %Response.WriteLine(".jet-flipcard.flipped .jet-flipcard-inner{transform:rotateY(180deg);}");
      %Response.WriteLine(".jet-flipcard-front,.jet-flipcard-back{position:absolute;width:100%;height:100%;backface-visibility:hidden;border:1px solid #ddd;border-radius:8px;padding:16px;box-sizing:border-box;background:#fff;}");
      %Response.WriteLine(".jet-flipcard-back{transform:rotateY(180deg);}");
      %Response.WriteLine(".jet-tabs-headers{display:flex;border-bottom:2px solid #eee;margin-bottom:12px;}");
      %Response.WriteLine(".jet-tab-btn{padding:8px 16px;border:none;background:none;cursor:pointer;font-weight:600;color:#777;border-bottom:2px solid transparent;margin-bottom:-2px;}");
      %Response.WriteLine(".jet-tab-btn.active{color:#0078d7;border-bottom-color:#0078d7;}");
      %Response.WriteLine(".jet-tab-panel{display:none;}");
      %Response.WriteLine(".jet-tab-panel.active{display:block;}");
      %Response.WriteLine("</style>");
      %Response.WriteLine("<script>function jetTabSwitch(btn,idx){var t=btn.closest('.jet-tabs');t.querySelectorAll('.jet-tab-btn').forEach(function(b,i){b.classList.toggle('active',i===idx);});t.querySelectorAll('.jet-tab-panel').forEach(function(p,i){p.classList.toggle('active',i===idx);});}</script>");
   End-If;

   %Response.WriteLine("</head><body data-oj-binding-provider=""none"">");
   %Response.WriteLine(&bodyHtml);
   %Response.WriteLine("</body></html>");

End-Function;

import OU_JET_PACK:Model:PageDesign;
import OU_JET_PACK:Storage:DesignRepository;
import OU_JET_PACK:Security:AccessCheck;
import OU_JET_PACK:Render:DesignerAssets;
import OU_JET_PACK:Utils:JsonUtil;
import OU_JET_PACK:Layout:ComponentRegistry;

Function JSONEscape(&s As string) Returns string
   &s = Substitute(&s, "\", "\\");
   &s = Substitute(&s, """", "\""");
   &s = Substitute(&s, Char(13), "\r");
   &s = Substitute(&s, Char(10), "\n");
   &s = Substitute(&s, Char(9), "\t");
   Return &s;
End-Function;

Function GetRequireConfigJs(&siteBase As string) Returns string
   Return GetHTMLText(HTML.OU_OJET_REQUIRE_CONFIG, &siteBase);
End-Function;

Function GetDesignerBodyHtml() Returns string
   Local string &h;

   &h = &h | Char(10) | "<div id='designerRoot'>";

   /* --- Toolbar --- */
   &h = &h | Char(10) | "  <div class='pgdsn-toolbar'>";
   &h = &h | Char(10) | "    <div class='pgdsn-toolbar-left'>";
   &h = &h | Char(10) | "      <span class='pgdsn-icon-title'>&#9635;</span>";
   &h = &h | Char(10) | "      <span class='pgdsn-page-title' data-bind='text: pageTitle'></span>";
   &h = &h | Char(10) | "    </div>";
   &h = &h | Char(10) | "    <div class='pgdsn-toolbar-right'>";
   &h = &h | Char(10) | "      <button class='pgdsn-icon-btn' data-bind='click: togglePreview' title='Preview'>&#128065;</button>";
   &h = &h | Char(10) | "      <button class='pgdsn-icon-btn' data-bind='click: openSettings' title='Settings'>&#9881;</button>";
   &h = &h | Char(10) | "      <button class='pgdsn-save-btn' data-bind='click: saveDesign, text: saving() ? ""Saving..."" : ""Save"", disable: saving'></button>";
   &h = &h | Char(10) | "      <button class='pgdsn-icon-btn' data-bind='click: closeDesigner' title='Close'>&#10005;</button>";
   &h = &h | Char(10) | "    </div>";
   &h = &h | Char(10) | "  </div>";

   /* --- Canvas --- */
   &h = &h | Char(10) | "  <div class='pgdsn-canvas'>";
   &h = &h | Char(10) | "    <h1 class='pgdsn-studio-title'>PageBuilder Studio</h1>";
   &h = &h | Char(10) | "    <p class='pgdsn-studio-sub'>Build your landing page by adding rows and widgets</p>";

   &h = &h | Char(10) | "    <!-- ko foreach: rows -->";
   &h = &h | Char(10) | "    <div class='pgdsn-row-wrapper'>";
   &h = &h | Char(10) | "      <div class='pgdsn-row-badge'>";
   &h = &h | Char(10) | "        <span data-bind=""text: 'Row ' + rowSeq + ' \u2014 ' + layoutLabel()""></span>";
   &h = &h | Char(10) | "        <span class='pgdsn-row-actions'>";
   &h = &h | Char(10) | "          <button data-bind='click: $parent.deleteRow' title='Delete row'>&#128465;</button>";
   &h = &h | Char(10) | "        </span>";
   &h = &h | Char(10) | "      </div>";
   &h = &h | Char(10) | "      <div class='oj-flex pgdsn-row' data-bind=""style: { backgroundColor: bgColor, backgroundImage: bgImage() ? 'url(' + bgImage() + ')' : 'none' }"">";
   &h = &h | Char(10) | "        <!-- ko foreach: cols -->";
   &h = &h | Char(10) | "        <div class='oj-flex-item pgdsn-col' data-bind=""style: { flexBasis: colWidthPct() + '%' }, click: function(data) { $parents[1].selectCell($parent, data); }"">";
   &h = &h | Char(10) | "          <!-- ko if: contentType() === 'TEXT' || contentType() === 'HTML' -->";
   &h = &h | Char(10) | "          <div data-bind='html: textValue'></div>";
   &h = &h | Char(10) | "          <!-- /ko -->";
   &h = &h | Char(10) | "          <!-- ko if: contentType() === 'IMAGE' -->";
   &h = &h | Char(10) | "          <img class='pgdsn-col-image' data-bind='attr: { src: imageUrl }'/>";
   &h = &h | Char(10) | "          <!-- /ko -->";
   &h = &h | Char(10) | "          <!-- ko if: contentType() === 'LINK' -->";
   &h = &h | Char(10) | "          <a class='oj-button' data-bind='attr: { href: linkUrl }, text: linkLabel'></a>";
   &h = &h | Char(10) | "          <!-- /ko -->";
   &h = &h | Char(10) | "        </div>";
   &h = &h | Char(10) | "        <!-- /ko -->";
   &h = &h | Char(10) | "      </div>";
   &h = &h | Char(10) | "    </div>";
   &h = &h | Char(10) | "    <!-- /ko -->";

   &h = &h | Char(10) | "    <button class='pgdsn-add-row-btn' data-bind='click: openAddRowPanel'>+ Add Row</button>";
   &h = &h | Char(10) | "  </div>";

   /* --- Slide-out Add Row panel --- */
   &h = &h | Char(10) | "  <div class='pgdsn-slideout' data-bind=""css: { 'pgdsn-slideout-open': showAddRowPanel }"">";
   &h = &h | Char(10) | "    <div class='pgdsn-slideout-header'>";
   &h = &h | Char(10) | "      <span>Add New Row</span>";
   &h = &h | Char(10) | "      <button data-bind='click: closeAddRowPanel'>&#10005;</button>";
   &h = &h | Char(10) | "    </div>";
   &h = &h | Char(10) | "    <div class='pgdsn-slideout-body'>";
   &h = &h | Char(10) | "      <p class='pgdsn-slideout-label'>Choose a layout for the new row:</p>";
   &h = &h | Char(10) | "      <!-- ko foreach: layoutOptions -->";
   &h = &h | Char(10) | "      <div class='pgdsn-layout-thumb' data-bind='click: $parent.selectLayout'>";
   &h = &h | Char(10) | "        <div class='pgdsn-layout-bars' data-bind='foreach: segments'>";
   &h = &h | Char(10) | "          <span class='pgdsn-layout-bar' data-bind=""style: { flexBasis: $data + '%' }""></span>";
   &h = &h | Char(10) | "        </div>";
   &h = &h | Char(10) | "        <div class='pgdsn-layout-label' data-bind='text: label'></div>";
   &h = &h | Char(10) | "      </div>";
   &h = &h | Char(10) | "      <!-- /ko -->";
   &h = &h | Char(10) | "    </div>";
   &h = &h | Char(10) | "  </div>";

   &h = &h | Char(10) | "</div>";

   Return &h;
End-Function;

Function GetDesignerCss() Returns string
   Local string &c;

   &c = &c | Char(10) | "body { margin:0; font-family:Arial,sans-serif; background:#faf9f7; }";
   &c = &c | Char(10) | "#designerRoot { min-height:100vh; }";

   /* Toolbar */
   &c = &c | Char(10) | ".pgdsn-toolbar { display:flex; justify-content:space-between; align-items:center; padding:10px 20px; background:#fff; border-bottom:1px solid #ddd; }";
   &c = &c | Char(10) | ".pgdsn-toolbar-left { display:flex; align-items:center; gap:8px; font-weight:600; }";
   &c = &c | Char(10) | ".pgdsn-icon-title { color:#f0ad4e; }";
   &c = &c | Char(10) | ".pgdsn-toolbar-right { display:flex; align-items:center; gap:8px; }";
   &c = &c | Char(10) | ".pgdsn-icon-btn { border:1px solid #ccc; background:#fff; border-radius:4px; width:34px; height:34px; cursor:pointer; font-size:16px; }";
   &c = &c | Char(10) | ".pgdsn-icon-btn:hover { background:#f2f2f2; }";
   &c = &c | Char(10) | ".pgdsn-save-btn { background:#1a1a1a; color:#fff; border:none; border-radius:4px; padding:8px 18px; cursor:pointer; font-weight:600; }";
   &c = &c | Char(10) | ".pgdsn-save-btn:disabled { opacity:0.6; cursor:default; }";

   /* Canvas */
   &c = &c | Char(10) | ".pgdsn-canvas { max-width:1000px; margin:0; padding:30px 20px 80px; }";
   &c = &c | Char(10) | ".pgdsn-studio-title { font-size:32px; margin:0 0 4px; }";
   &c = &c | Char(10) | ".pgdsn-studio-sub { color:#777; margin:0 0 24px; }";

   /* Row badge + row */
   &c = &c | Char(10) | ".pgdsn-row-wrapper { margin-bottom:24px; border:1px dashed #ccc; border-radius:4px; }";
   &c = &c | Char(10) | ".pgdsn-row-badge { display:flex; justify-content:space-between; align-items:center; font-size:12px; color:#999; padding:4px 10px; background:#f5f4f2; }";
   &c = &c | Char(10) | ".pgdsn-row-actions button { border:none; background:none; cursor:pointer; font-size:13px; }";
   &c = &c | Char(10) | ".pgdsn-row { padding:0; background-size:cover; background-position:center; }";
   &c = &c | Char(10) | ".pgdsn-col { padding:16px; box-sizing:border-box; border-left:1px dashed #e0e0e0; min-height:60px; cursor:pointer; }";
   &c = &c | Char(10) | ".pgdsn-col:first-child { border-left:none; }";
   &c = &c | Char(10) | ".pgdsn-col:hover { background:rgba(0,120,215,0.05); }";
   &c = &c | Char(10) | ".pgdsn-col-image { max-width:100%; display:block; }";

   &c = &c | Char(10) | ".pgdsn-add-row-btn { border:1px solid #ccc; background:#fff; border-radius:4px; padding:8px 16px; cursor:pointer; }";
   &c = &c | Char(10) | ".pgdsn-add-row-btn:hover { background:#f2f2f2; }";

   /* Slide-out panel */
   &c = &c | Char(10) | ".pgdsn-slideout { position:fixed; top:0; right:-380px; width:360px; height:100vh; background:#fff; box-shadow:-2px 0 8px rgba(0,0,0,0.15); transition:right 0.25s ease; z-index:1000; overflow-y:auto; }";
   &c = &c | Char(10) | ".pgdsn-slideout-open { right:0; }";
   &c = &c | Char(10) | ".pgdsn-slideout-header { display:flex; justify-content:space-between; align-items:center; padding:16px 20px; border-bottom:1px solid #eee; font-weight:600; }";
   &c = &c | Char(10) | ".pgdsn-slideout-header button { border:none; background:none; cursor:pointer; font-size:16px; }";
   &c = &c | Char(10) | ".pgdsn-slideout-body { padding:16px 20px; }";
   &c = &c | Char(10) | ".pgdsn-slideout-label { color:#777; font-size:13px; margin-bottom:12px; }";

   &c = &c | Char(10) | ".pgdsn-layout-thumb { border:1px solid #ddd; border-radius:4px; padding:8px; margin-bottom:12px; cursor:pointer; }";
   &c = &c | Char(10) | ".pgdsn-layout-thumb:hover { border-color:#0078d7; }";
   &c = &c | Char(10) | ".pgdsn-layout-bars { display:flex; gap:3px; height:36px; margin-bottom:6px; }";
   &c = &c | Char(10) | ".pgdsn-layout-bar { background:#0078d7; opacity:0.25; border-radius:2px; }";
   &c = &c | Char(10) | ".pgdsn-layout-thumb:hover .pgdsn-layout-bar { opacity:0.6; }";
   &c = &c | Char(10) | ".pgdsn-layout-label { text-align:center; font-size:12px; color:#777; }";

   Return &c;
End-Function;

Function GetDesignerViewModelJs() Returns string
   Local string &j;

   &j = &j | Char(10) | "var LAYOUT_OPTIONS = [";
   &j = &j | Char(10) | "  { code:'1COL',        label:'100%',              segments:[100] },";
   &j = &j | Char(10) | "  { code:'2COL_5050',   label:'50% / 50%',         segments:[50,50] },";
   &j = &j | Char(10) | "  { code:'2COL_7030',   label:'70% / 30%',         segments:[70,30] },";
   &j = &j | Char(10) | "  { code:'2COL_3070',   label:'30% / 70%',         segments:[30,70] },";
   &j = &j | Char(10) | "  { code:'2COL_6040',   label:'60% / 40%',         segments:[60,40] },";
   &j = &j | Char(10) | "  { code:'2COL_4060',   label:'40% / 60%',         segments:[40,60] },";
   &j = &j | Char(10) | "  { code:'3COL_333333', label:'33% / 33% / 33%',   segments:[33.34,33.33,33.33] },";
   &j = &j | Char(10) | "  { code:'3COL_502525', label:'50% / 25% / 25%',   segments:[50,25,25] },";
   &j = &j | Char(10) | "  { code:'3COL_255025', label:'25% / 50% / 25%',   segments:[25,50,25] },";
   &j = &j | Char(10) | "  { code:'3COL_252550', label:'25% / 25% / 50%',   segments:[25,25,50] }";
   &j = &j | Char(10) | "];";

   &j = &j | Char(10) | "function layoutByCode(code) {";
   &j = &j | Char(10) | "  for (var i=0;i<LAYOUT_OPTIONS.length;i++) { if (LAYOUT_OPTIONS[i].code===code) return LAYOUT_OPTIONS[i]; }";
   &j = &j | Char(10) | "  return LAYOUT_OPTIONS[0];";
   &j = &j | Char(10) | "}";

   /* --- Build a col object from server data + its position within the row's layout --- */
   &j = &j | Char(10) | "function buildCol(colData, segments, idx) {";
   &j = &j | Char(10) | "  return {";
   &j = &j | Char(10) | "    colSeq: colData.colSeq,";
   &j = &j | Char(10) | "    contentType: ko.observable(colData.contentType || 'TEXT'),";
   &j = &j | Char(10) | "    textValue: ko.observable(colData.textValue || ''),";
   &j = &j | Char(10) | "    imageUrl: ko.observable(colData.imageUrl || ''),";
   &j = &j | Char(10) | "    linkUrl: ko.observable(colData.linkUrl || ''),";
   &j = &j | Char(10) | "    linkLabel: ko.observable(colData.linkLabel || ''),";
   &j = &j | Char(10) | "    colWidthPct: ko.observable(segments[idx] || (100/segments.length))";
   &j = &j | Char(10) | "  };";
   &j = &j | Char(10) | "}";

   /* --- Build a row object from server data --- */
   &j = &j | Char(10) | "function buildRow(rowData) {";
   &j = &j | Char(10) | "  var layoutDef = layoutByCode(rowData.layout);";
   &j = &j | Char(10) | "  var row = {";
   &j = &j | Char(10) | "    rowSeq: rowData.rowSeq,";
   &j = &j | Char(10) | "    layout: ko.observable(rowData.layout),";
   &j = &j | Char(10) | "    bgColor: ko.observable(rowData.bgColor || ''),";
   &j = &j | Char(10) | "    bgImage: ko.observable(rowData.bgImage || ''),";
   &j = &j | Char(10) | "    cols: ko.observableArray([])";
   &j = &j | Char(10) | "  };";
   &j = &j | Char(10) | "  row.layoutLabel = ko.computed(function() { return layoutByCode(row.layout()).label; });";
   &j = &j | Char(10) | "  var segs = layoutDef.segments;";
   &j = &j | Char(10) | "  (rowData.cols||[]).forEach(function(c, idx) { row.cols.push(buildCol(c, segs, idx)); });";
   &j = &j | Char(10) | "  return row;";
   &j = &j | Char(10) | "}";

   /* --- The Knockout viewModel --- */
   &j = &j | Char(10) | "var viewModel = {";
   &j = &j | Char(10) | "  pageTitle: ko.observable(PGDSN_DATA.descr || PGDSN_DATA.designId),";
   &j = &j | Char(10) | "  lastUpdDttm: ko.observable(PGDSN_DATA.lastUpdDttm),";
   &j = &j | Char(10) | "  rows: ko.observableArray((PGDSN_DATA.rows||[]).map(buildRow)),";
   &j = &j | Char(10) | "  layoutOptions: LAYOUT_OPTIONS,";
   &j = &j | Char(10) | "  showAddRowPanel: ko.observable(false),";
   &j = &j | Char(10) | "  saving: ko.observable(false)";
   &j = &j | Char(10) | "};";

   &j = &j | Char(10) | "viewModel.openAddRowPanel = function() { viewModel.showAddRowPanel(true); };";
   &j = &j | Char(10) | "viewModel.closeAddRowPanel = function() { viewModel.showAddRowPanel(false); };";

   &j = &j | Char(10) | "viewModel.selectLayout = function(layoutDef) {";
   &j = &j | Char(10) | "  var maxSeq = 0;";
   &j = &j | Char(10) | "  viewModel.rows().forEach(function(r) { if (r.rowSeq > maxSeq) maxSeq = r.rowSeq; });";
   &j = &j | Char(10) | "  var newRowData = { rowSeq: maxSeq + 10, layout: layoutDef.code, bgColor:'', bgImage:'',";
   &j = &j | Char(10) | "    cols: layoutDef.segments.map(function(pct, i) { return { colSeq: i+1, contentType:'TEXT', textValue:'New content' }; }) };";
   &j = &j | Char(10) | "  viewModel.rows.push(buildRow(newRowData));";
   &j = &j | Char(10) | "  viewModel.closeAddRowPanel();";
   &j = &j | Char(10) | "};";

   &j = &j | Char(10) | "viewModel.deleteRow = function(row) {";
   &j = &j | Char(10) | "  if (confirm('Delete this row?')) { viewModel.rows.remove(row); }";
   &j = &j | Char(10) | "};";

   /* Placeholder inline editing - simple prompt() until a real editing panel is designed */
   &j = &j | Char(10) | "viewModel.selectCell = function(row, col) {";
   &j = &j | Char(10) | "  var ct = col.contentType();";
   &j = &j | Char(10) | "  if (ct === 'TEXT' || ct === 'HTML') {";
   &j = &j | Char(10) | "    var v = prompt('Edit text:', col.textValue()); if (v !== null) col.textValue(v);";
   &j = &j | Char(10) | "  } else if (ct === 'IMAGE') {";
   &j = &j | Char(10) | "    var v = prompt('Image URL:', col.imageUrl()); if (v !== null) col.imageUrl(v);";
   &j = &j | Char(10) | "  } else if (ct === 'LINK') {";
   &j = &j | Char(10) | "    var u = prompt('Link URL:', col.linkUrl()); if (u !== null) col.linkUrl(u);";
   &j = &j | Char(10) | "    var l = prompt('Link label:', col.linkLabel()); if (l !== null) col.linkLabel(l);";
   &j = &j | Char(10) | "  }";
   &j = &j | Char(10) | "};";

   &j = &j | Char(10) | "viewModel.openSettings = function() {";
   &j = &j | Char(10) | "  var v = prompt('Page title:', viewModel.pageTitle()); if (v !== null) viewModel.pageTitle(v);";
   &j = &j | Char(10) | "};";

   &j = &j | Char(10) | "viewModel.togglePreview = function() {";
   &j = &j | Char(10) | "  var url = window.location.pathname.replace('" | "IScript_VPOrchestrator" | "','" | "IScript_JETLandingPage" | "') + '?design=' + PGDSN_DATA.designId;";
   &j = &j | Char(10) | "  window.open(url, '_blank');";
   &j = &j | Char(10) | "};";

   &j = &j | Char(10) | "viewModel.closeDesigner = function() {";
   &j = &j | Char(10) | "  if (confirm('Leave designer? Unsaved changes will be lost.')) { window.close(); }";
   &j = &j | Char(10) | "};";

   &j = &j | Char(10) | "viewModel.saveDesign = function() {";
   &j = &j | Char(10) | "  viewModel.saving(true);";
   &j = &j | Char(10) | "  var payload = { designId: PGDSN_DATA.designId, csrf: PGDSN_CSRF, lastUpdDttm: viewModel.lastUpdDttm(),";
   &j = &j | Char(10) | "    descr: viewModel.pageTitle(),";
   &j = &j | Char(10) | "    rows: viewModel.rows().map(function(r) { return { rowSeq: r.rowSeq, layout: r.layout(), bgColor: r.bgColor(), bgImage: r.bgImage(),";
   &j = &j | Char(10) | "      cols: r.cols().map(function(c) { return { colSeq: c.colSeq, contentType: c.contentType(), textValue: c.textValue(), imageUrl: c.imageUrl(), linkUrl: c.linkUrl(), linkLabel: c.linkLabel() }; }) }; })";
   &j = &j | Char(10) | "  };";
   /*
   &j = &j | Char(10) | "  fetch(PGDSN_SAVE_URL, { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify(payload) })";
   &j = &j | Char(10) | "    .then(function(resp) { return resp.json().then(function(data) { return { status: resp.status, data: data }; }); })";
   &j = &j | Char(10) | "    .then(function(result) {";
   &j = &j | Char(10) | "      viewModel.saving(false);";
   &j = &j | Char(10) | "      if (result.status === 200) { viewModel.lastUpdDttm(result.data.lastUpdDttm); alert('Saved.'); }";
   &j = &j | Char(10) | "      else if (result.status === 409) { alert('This design was changed by someone else. Reload before saving.'); }";
   &j = &j | Char(10) | "      else { alert('Save failed: ' + (result.data.message || result.status)); }";
   &j = &j | Char(10) | "    })";
*/
   &j = &j | Char(10) | "  fetch(PGDSN_SAVE_URL, { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify(payload) }) ";
   &j = &j | Char(10) | "    .then(function(resp) { return resp.json(); }) ";
   &j = &j | Char(10) | "    .then(function(data) { ";
   &j = &j | Char(10) | "      viewModel.saving(false); ";
   &j = &j | Char(10) | "      if (data.status === 'ok') { viewModel.lastUpdDttm(data.lastUpdDttm); alert('Saved.'); } ";
   &j = &j | Char(10) | "      else if (data.status === 'conflict') { alert('This design was changed by someone else. Reload before saving.'); } ";
   &j = &j | Char(10) | "      else { alert('Save failed: ' + (data.message || 'Unknown error')); } ";
   &j = &j | Char(10) | "    }) ";

   &j = &j | Char(10) | "    .catch(function(err) { viewModel.saving(false); alert('Save failed: ' + err); });";
   &j = &j | Char(10) | "};";

   &j = &j | Char(10) | "ko.applyBindings(viewModel, document.getElementById('designerRoot'));";

   Return &j;
End-Function;


Function GetComponentRegistryJson() Returns string
   Local string &j;
   &j = "[";
   &j = &j | "{""tag"":""oj-button2"",""label"":""Button"",""defaultProps"":{""label"":""Click Me"",""chroming"":""solid""}},";
   &j = &j | "{""tag"":""oj-button"",""label"":""Button"",""defaultProps"":{""label"":""Click Me"",""chroming"":""solid""}},";
   &j = &j | "{""tag"":""oj-input-text"",""label"":""Text Input"",""defaultProps"":{""placeholder"":""""}},";
   &j = &j | "{""tag"":""oj-input-number"",""label"":""Number Input"",""defaultProps"":{""placeholder"":"""",""min"":0,""max"":100}}";
   &j = &j | "]";
   Return &j;
End-Function;


Function GenerateSaveUrl() Returns string
   Local string &url;
   Local integer &qPos;

   &url = %Request.FullURI;
   &qPos = Find("?", &url);
   If &qPos > 0 Then
      &url = Substring(&url, 1, &qPos - 1);
   End-If;
   &url = Substitute(&url, "IScript_VPOrchestrator", "IScript_SaveDesign");
   &url = &url | "?&postDataBin=y";
   Return &url;
End-Function;


Function IScript_VPOrchestrator()
   Local string &designId, &siteBase, &csrfToken;
   Local OU_JET_PACK:Security:AccessCheck &access = create OU_JET_PACK:Security:AccessCheck();
   Local OU_JET_PACK:Storage:DesignRepository &repo = create OU_JET_PACK:Storage:DesignRepository();
   Local OU_JET_PACK:Render:DesignerAssets &assets = create OU_JET_PACK:Render:DesignerAssets();
   Local OU_JET_PACK:Model:PageDesign &design;

   If Not &access.IsAuthorizedDesigner() Then
      %Response.SetContentType("text/html");
      %Response.WriteLine("Not authorized.");
      Return;
   End-If;

   &designId = %Request.GetParameter("design");
   If &designId = "" Then
      %Response.SetContentType("text/html");
      %Response.WriteLine("<script>window.location.href='WEBLIB_OU_LP.ISCRIPT2.FieldFormula.IScript_DesignList';</script>");
      Return;
   End-If;

   %Response.SetContentType("text/html");
   &siteBase = "/cs/" | %DbName | "/oraclejet";

   &csrfToken = String(Rand() * 1000000000) | "-" | String(%Datetime);
   %Session.SetAttribute("PGDSN_CSRF_TOKEN", &csrfToken);

   &design = &repo.Load(&designId);
   /* Load() sets design.IsNew when no header exists yet - PageId still needs
      setting explicitly since a not-found Load doesn't have it populated */
   &design.PageId = &designId;

   %Response.WriteLine("<!DOCTYPE html><html><head>");
   %Response.WriteLine("<link rel='stylesheet' href='" | &siteBase | "/css/libs/oj/14.1.1/redwood/oj-redwood-min.css'/>");
   %Response.WriteLine("<script src='" | &siteBase | "/js/libs/require/require-debug.js'></script>");
   %Response.WriteLine("<style>" | &assets.GetCss() | "</style>");
   %Response.WriteLine("<script>");
   %Response.WriteLine("var PGDSN_DATA = " | &design.ToJson() | "; ");
   %Response.WriteLine("var PGDSN_CSRF = '" | &csrfToken | "'; ");
   %Response.WriteLine("var PGDSN_SAVE_URL = '" | GenerateSaveUrl() | "'; ");
   %Response.WriteLine(&assets.GetRequireConfigJs(&siteBase));

   rem %Response.WriteLine("require(['ojs/ojcore','knockout','ojs/ojknockout','ojs/ojbutton','ojs/ojbutton2','ojs/ojbuttonlegacy','ojs/ojinputtext','ojs/ojinputnumber'], function(oj, ko, ojknockout, ojbutton, ojinputtext, ojinputnumber) {");

   Local OU_JET_PACK:Layout:ComponentRegistry &registry = create OU_JET_PACK:Layout:ComponentRegistry();
   Local array of string &mods = &registry.GetAllRequireModules();
   Local string &modList, &paramList;
   Local integer &m;

   &modList = "'ojs/ojcore','knockout','ojs/ojknockout'";
   &paramList = "oj, ko, ojknockout";
   For &m = 1 To &mods.Len
      &modList = &modList | ",'" | &mods [&m] | "'";
      &paramList = &paramList | ", _m" | &m;
   End-For;

   %Response.WriteLine("require([" | &modList | "], function(" | &paramList | ") {");


   %Response.WriteLine(&assets.GetViewModelJs());
   %Response.WriteLine("});");
   %Response.WriteLine("</script></head><body>");
   %Response.WriteLine(&assets.GetBodyHtml());
   %Response.WriteLine("</body></html>");
End-Function;




Function IScript_SaveDesign()
   Local string &body, &designId, &csrfSubmitted, &csrfSession, &lastSeenDttm;
   Local OU_JET_PACK:Security:AccessCheck &access = create OU_JET_PACK:Security:AccessCheck();
   Local OU_JET_PACK:Storage:DesignRepository &repo = create OU_JET_PACK:Storage:DesignRepository();
   Local OU_JET_PACK:Utils:JsonUtil &u = create OU_JET_PACK:Utils:JsonUtil();
   Local JsonObject &jo;
   Local OU_JET_PACK:Model:PageDesign &design;

   %Response.SetContentType("application/json");

   If Not &access.IsAuthorizedDesigner() Then
      %Response.WriteLine("{""status"":""error"",""message"":""Not authorized.""}");
      Return;
   End-If;

   try
      &body = %Request.GetContentBody();
      Local JsonParser &jp = CreateJsonParser();
      If Not &jp.Parse(&body) Then
         /*Error*/
      End-If;
      &jo = &jp.GetRootObject();
   catch Exception &e
      rem TODO %Response.SetStatusCode(400);
      %Response.WriteLine("{""status"":""error"",""message"":""" | &e.ToString() | """}");
      Return;
   end-try;

   &designId = &jo.GetString("designId");

   If &designId = "" Then
      %Response.WriteLine("{""status"":""error"",""message"":""Missing design ID.""}");
      Return;
   End-If;

   &csrfSubmitted = &jo.GetString("csrf");
   &lastSeenDttm = &jo.GetString("lastUpdDttm");
   &descr = &jo.GetString("descr");

   /*
TODO   - IGNORE FOR NOW
   &csrfSession = %Session.GetAttribute("PGDSN_CSRF_TOKEN");
   If &csrfSubmitted <> &csrfSession Or
         &csrfSubmitted = "" Then
      %Response.WriteLine("{""status"":""error"",""message"":""Invalid session token, please reload the designer.""}");
      Return;
   End-If;
*/

   &design = create OU_JET_PACK:Model:PageDesign(&designId);
   &csrfSubmitted = &design.FromJsonBody(&body);

   If &repo.Exists(&designId) Then
      Local OU_JET_PACK:Model:PageDesign &current = &repo.Load(&designId);
      If &current.LastUpdDttm <> &design.LastUpdDttm Then
         /* TODO   - IGNORE FOR NOW
		 %Response.WriteLine("{""status"":""conflict"",""message"":""This design was changed by someone else. Reload before saving.""}");
         Return;
*/
      End-If;
   End-If;

   Local boolean &result = &repo.Save(&design);

   /* Reload to get the freshly-stamped LastUpdDttm for the client to store */
   &design = &repo.Load(&designId);

   %Response.WriteLine("{""status"":""ok"",""lastUpdDttm"":""" | &u.EscapeJson(&design.LastUpdDttm) | """}");
End-Function;



Function IScript_DesignList()
   Local OU_JET_PACK:Security:AccessCheck &access = create OU_JET_PACK:Security:AccessCheck();
   Local OU_JET_PACK:Storage:DesignRepository &repo = create OU_JET_PACK:Storage:DesignRepository();
   Local array of OU_JET_PACK:Model:PageDesign &list;
   Local OU_JET_PACK:Model:PageDesign &d;
   Local integer &i;
   Local string &h;

   If Not &access.IsAuthorizedDesigner() Then
      %Response.SetContentType("text/html");
      %Response.WriteLine("Not authorized.");
      Return;
   End-If;

   %Response.SetContentType("text/html");
   &list = &repo.ListHeaders();

   &h = &h | "<!DOCTYPE html><html><head><title>Page Designs</title>";
   &h = &h | "<style>";
   &h = &h | "body{font-family:Arial,sans-serif;max-width:700px;margin:40px auto;color:#222;}";
   &h = &h | "h1{font-size:24px;} table{width:100%;border-collapse:collapse;margin-bottom:30px;}";
   &h = &h | "td,th{padding:8px 10px;border-bottom:1px solid #eee;text-align:left;}";
   &h = &h | "a{color:#0078d7;text-decoration:none;} a:hover{text-decoration:underline;}";
   &h = &h | ".newform{border:1px solid #ddd;border-radius:6px;padding:20px;background:#fafafa;}";
   &h = &h | "input[type=text]{padding:8px;width:260px;border:1px solid #ccc;border-radius:4px;}";
   &h = &h | "button{padding:8px 18px;border:none;background:#1a1a1a;color:#fff;border-radius:4px;cursor:pointer;}";
   &h = &h | "</style></head><body data-oj-binding-provider=""none"">";

   &h = &h | "<h1>Page Designs</h1>";
   &h = &h | "<table><tr><th>Design</th><th>ID</th><th>Status</th><th></th></tr>";

   For &i = 1 To &list.Len
      &d = &list [&i];
      &h = &h | "<tr><td>" | &d.Descr | "</td><td>" | &d.PageId | "</td>";
      &h = &h | "<td>" | &d.PgdsnStatus | "</td>";
      &h = &h | "<td><a href='WEBLIB_OU_LP.ISCRIPT2.FieldFormula.IScript_VPOrchestrator?design=" | &d.PageId | "'>Edit</a> &nbsp; ";
      &h = &h | "<a href='WEBLIB_OU_LP.ISCRIPT2.FieldFormula.IScript_JETLandingPage?design=" | &d.PageId | "' target='_blank'>View</a></td></tr>";
   End-For;

   If &list.Len = 0 Then
      &h = &h | "<tr><td colspan='4'><em>No designs yet.</em></td></tr>";
   End-If;
   &h = &h | "</table>";

   &h = &h | "<div class='newform'>";
   &h = &h | "<h3>Create New Design</h3>";
   &h = &h | "<form method='GET' action='IScript_VPOrchestrator'>";
   &h = &h | "<input type='text' name='design' placeholder='e.g. OPEN_ENROLLMENT1' maxlength='30' pattern='[A-Za-z0-9_]+' required title='Letters, numbers, underscore only'/>";
   &h = &h | " <button type='submit'>Create / Open</button>";
   &h = &h | "</form></div>";

   &h = &h | "</body></html>";
   %Response.WriteLine(&h);
End-Function;

row.hContStrData:
 HANDLE



              body { margin:0; font-family:Arial,sans-serif; background:#faf9f7; }
#designerRoot { min-height:100vh; }
.pgdsn-toolbar { display:flex; justify-content:space-between; align-items:center; padding:10px 20px; background:#fff; border-bottom:1px solid #ddd; }
.pgdsn-toolbar-left { display:flex; align-items:center; gap:8px; font-weight:600; }
.pgdsn-icon-title { color:#f0ad4e; }
.pgdsn-toolbar-right { display:flex; align-items:center; gap:8px; }
.pgdsn-icon-btn { border:1px solid #ccc; background:#fff; border-radius:4px; width:34px; height:34px; cursor:pointer; font-size:16px; }
.pgdsn-icon-btn:hover { background:#f2f2f2; }
.pgdsn-save-btn { background:#1a1a1a; color:#fff; border:none; border-radius:4px; padding:8px 18px; cursor:pointer; font-weight:600; }
.pgdsn-save-btn:disabled { opacity:0.6; cursor:default; }
.pgdsn-canvas { max-width:1000px; margin:0; padding:30px 20px 80px; }
.pgdsn-studio-title { font-size:32px; margin:0 0 4px; }
.pgdsn-studio-sub { color:#777; margin:0 0 24px; }
.pgdsn-row-wrapper { margin-bottom:24px; border:1px dashed #ccc; border-radius:4px; }
.pgdsn-row-badge { display:flex; justify-content:space-between; align-items:center; font-size:12px; color:#999; padding:4px 10px; background:#f5f4f2; }
.pgdsn-row-actions button { border:none; background:none; cursor:pointer; font-size:13px; }
.pgdsn-row { padding:0; background-size:cover; background-position:center; }
.pgdsn-col { padding:16px; box-sizing:border-box; border-left:1px dashed #e0e0e0; min-height:60px; cursor:pointer; }
.pgdsn-col:first-child { border-left:none; }
.pgdsn-col:hover { background:rgba(0,120,215,0.05); }
.pgdsn-col-image { max-width:100%; display:block; }
.pgdsn-add-row-btn { border:1px solid #ccc; background:#fff; border-radius:4px; padding:8px 16px; cursor:pointer; }
.pgdsn-add-row-btn:hover { background:#f2f2f2; }
.pgdsn-slideout { position:fixed; top:0; right:-380px; width:360px; height:100vh; background:#fff; box-shadow:-2px 0 8px rgba(0,0,0,0.15); transition:right 0.25s ease; z-index:1000; overflow-y:auto; }
.pgdsn-slideout-open { right:0; }
.pgdsn-slideout-header { display:flex; justify-content:space-between; align-items:center; padding:16px 20px; border-bottom:1px solid #eee; font-weight:600; }
.pgdsn-slideout-header button { border:none; background:none; cursor:pointer; font-size:16px; }
.pgdsn-slideout-body { padding:16px 20px; }
.pgdsn-slideout-label { color:#777; font-size:13px; margin-bottom:12px; }
.pgdsn-layout-thumb { border:1px solid #ddd; border-radius:4px; padding:8px; margin-bottom:12px; cursor:pointer; }
.pgdsn-layout-thumb:hover { border-color:#0078d7; }
.pgdsn-layout-bars { display:flex; gap:3px; height:36px; margin-bottom:6px; }
.pgdsn-layout-bar { background:#0078d7; opacity:0.25; border-radius:2px; }
.pgdsn-layout-thumb:hover .pgdsn-layout-bar { opacity:0.6; }
.pgdsn-layout-label { text-align:center; font-size:12px; color:#777; }
.pgdsn-field-label { font-size:12px; color:#666; margin:16px 0 4px; font-weight:600; }
.pgdsn-field { width:100%; display:block; margin-bottom:4px; }
.pgdsn-textarea { font-family:Arial,sans-serif; font-size:14px; padding:8px; border:1px solid #ccc; border-radius:4px; box-sizing:border-box; resize:vertical; }
.pgdsn-select { font-family:Arial,sans-serif; font-size:14px; padding:8px; border:1px solid #ccc; border-radius:4px; box-sizing:border-box; }
.pgdsn-active-toggle { display:flex; align-items:center; gap:8px; font-size:13px; font-weight:600; margin-bottom:8px; }
.pgdsn-error { color:#c0392b; font-size:12px; margin:2px 0 8px; }
.pgdsn-col-inactive { opacity:0.35; }
.pgdsn-drag-handle { cursor:grab; margin-right:8px; color:#999; user-select:none; letter-spacing:-2px; }
.pgdsn-drag-handle:active { cursor:grabbing; }
.pgdsn-col { position:relative; }
.pgdsn-col-drag-handle { position:absolute; top:4px; left:4px; cursor:grab; color:#999; background:rgba(255,255,255,0.85); border-radius:3px; padding:0 4px; font-size:13px; user-select:none; z-index:2; letter-spacing:-2px; }
.pgdsn-col-drag-handle:active { cursor:grabbing; }
.pgdsn-drop-target { outline:2px dashed #0078d7; outline-offset:-2px; }

 HANDLE



              var LAYOUT_OPTIONS = %Bind(:1);

var CONTENT_TYPE_OPTIONS = [
  { value:'TEXT'		, label:'Text' 						},
  { value:'HTML'		, label:'Raw HTML' 					},
  { value:'IMAGE'		, label:'Image' 					},
  { value:'LINK'		, label:'Button/Link' 				},
  { value:'COMPONENT'	, label:'JET Component' 			},
  { value:'CARD_FLIP'	, label:'JET Card (Flip)'			},
  { value:'TABS'		, label:'JET Tabbed Content' 		},
  { value:'COLLAPSIBLE' , label:'JET Collapsible Panel'     },
  { value:'WIDGET'		, label:'Custom App Class Widget' 	}
];

var COMPONENT_OPTIONS = %Bind(:2);

function layoutByCode(code) {
  for (var i=0;i<LAYOUT_OPTIONS.length;i++) { if (LAYOUT_OPTIONS[i].code===code) return LAYOUT_OPTIONS[i]; }
  return LAYOUT_OPTIONS[0];
}
   
ko.bindingHandlers.jetComponent = {
  init: function(element, valueAccessor) {
    var val = ko.unwrap(valueAccessor());
    if (!val.tag) return;
    var el = document.createElement(val.tag);
    var props = val.props || {};
    Object.keys(props).forEach(function(k) {
      try { el[k] = props[k]; } catch(e) { el.setAttribute(k, props[k]); }
    });
    element.appendChild(el);
    return { controlsDescendantBindings: true };
  }
};


var dragState = { type: null };

ko.bindingHandlers.rowDragHandle = {
  init: function(element, valueAccessor) {
    var row = valueAccessor();
    element.setAttribute('draggable', 'true');
    element.addEventListener('dragstart', function(e) {
      dragState = { type: 'row', rowIndex: viewModel.rows.indexOf(row) };
      e.dataTransfer.effectAllowed = 'move';
      e.stopPropagation();
    });
  }
};

ko.bindingHandlers.rowDropZone = {
  init: function(element, valueAccessor) {
    var row = valueAccessor();
    element.addEventListener('dragover', function(e) {
      if (dragState.type === 'row') { e.preventDefault(); element.classList.add('pgdsn-drop-target'); }
    });
    element.addEventListener('dragleave', function() { element.classList.remove('pgdsn-drop-target'); });
    element.addEventListener('drop', function(e) {
      if (dragState.type !== 'row') return;
      e.preventDefault();
      element.classList.remove('pgdsn-drop-target');
      var fromIdx = dragState.rowIndex;
      var toIdx = viewModel.rows.indexOf(row);
      if (fromIdx === toIdx) { dragState = { type: null }; return; }
      var rowsArr = viewModel.rows();
      var moved = rowsArr[fromIdx];
      rowsArr.splice(fromIdx, 1);
      rowsArr.splice(toIdx, 0, moved);
      rowsArr.forEach(function(r, i) { r.rowSeq = (i + 1) * 10; });
      viewModel.rows.valueHasMutated();
      dragState = { type: null };
    });
  }
};

ko.bindingHandlers.colDragHandle = {
  init: function(element, valueAccessor) {
    var data = valueAccessor();
    element.setAttribute('draggable', 'true');
    element.addEventListener('dragstart', function(e) {
      dragState = { type: 'col', row: data.row, colIndex: data.row.cols.indexOf(data.col) };
      e.dataTransfer.effectAllowed = 'move';
      e.stopPropagation();
    });
    element.addEventListener('click', function(e) { e.stopPropagation(); });
  }
};

ko.bindingHandlers.colDropZone = {
  init: function(element, valueAccessor) {
    var data = valueAccessor();
    element.addEventListener('dragover', function(e) {
      if (dragState.type === 'col' && dragState.row === data.row) { e.preventDefault(); element.classList.add('pgdsn-drop-target'); }
    });
    element.addEventListener('dragleave', function() { element.classList.remove('pgdsn-drop-target'); });
    element.addEventListener('drop', function(e) {
      if (dragState.type !== 'col' || dragState.row !== data.row) return;
      e.preventDefault();
      element.classList.remove('pgdsn-drop-target');
      var row = data.row;
      var fromIdx = dragState.colIndex;
      var toIdx = row.cols.indexOf(data.col);
      if (fromIdx === toIdx) { dragState = { type: null }; return; }
      var colsArr = row.cols();
      var moved = colsArr[fromIdx];
      colsArr.splice(fromIdx, 1);
      colsArr.splice(toIdx, 0, moved);
      var layoutDef = layoutByCode(row.layout());
      var segs = layoutDef.segments;
      colsArr.forEach(function(c, i) { c.colSeq = i + 1; c.colWidthPct(segs[i] || (100/colsArr.length)); });
      row.cols.valueHasMutated();
      dragState = { type: null };
    });
  }
};




   
function buildCol(colData, segments, idx) {
  var col = {
    colSeq: colData.colSeq,
    contentType: ko.observable(colData.contentType || 'TEXT'),
    textValue: ko.observable(colData.textValue || ''),
    imageUrl: ko.observable(colData.imageUrl || ''),
    linkUrl: ko.observable(colData.linkUrl || ''),
    linkLabel: ko.observable(colData.linkLabel || ''),
    componentTag: ko.observable(colData.componentTag || ''),
    componentProps: ko.observable(colData.componentProps || {}),
    componentOptions: ko.observable(colData.componentOptions || { items: [] }),
    active: ko.observable(colData.active !== false),
    altText: ko.observable(colData.altText || ''),
    widgetClassPath: ko.observable(colData.widgetClassPath || ''),
    widgetMethod: ko.observable(colData.widgetMethod || 'Render'),
    widgetProps: ko.observable(colData.widgetProps || {}),
    widgetPropsError: ko.observable(false),
    colWidthPct: ko.observable(segments[idx] || (100/segments.length)),
    structJson: ko.observable(colData.structJson || {}),
  };

  col.componentPropKeys = ko.pureComputed(function() { return Object.keys(col.componentProps() || {}); });

  col.widgetPropsRaw = ko.pureComputed({
    read: function() { return JSON.stringify(col.widgetProps(), null, 2); },
    write: function(val) {
      try { col.widgetProps(JSON.parse(val)); col.widgetPropsError(false); }
      catch (e) { col.widgetPropsError(true); }
    }
  });

  col.componentOptionsRaw = ko.pureComputed({
    read: function() {
      var items = (col.componentOptions() && col.componentOptions().items) || [];
      return items.map(function(i) { return i.value + '|' + i.label; }).join('\n');
    },
    write: function(val) {
      var items = val.split('\n').filter(function(l) { return l.trim(); }).map(function(line) {
        var parts = line.split('|');
        return { value: (parts[0]||'').trim(), label: (parts[1]||parts[0]||'').trim() };
      });
      col.componentOptions({ items: items });
    }
  });

  col.cardFront = ko.pureComputed({
    read: function() { return (col.structJson()||{}).front || ''; },
    write: function(v) { var s = col.structJson()||{}; s.front = v; col.structJson(s); }
  });
  col.cardBack = ko.pureComputed({
    read: function() { return (col.structJson()||{}).back || ''; },
    write: function(v) { var s = col.structJson()||{}; s.back = v; col.structJson(s); }
  });
  col.tabsRaw = ko.pureComputed({
    read: function() {
      var tabs = (col.structJson()||{}).tabs || [];
      return tabs.map(function(t) { return t.label + '\n===\n' + t.content; }).join('\n---TAB---\n');
    },
    write: function(v) {
      var tabs = v.split('---TAB---').map(function(chunk) {
        var parts = chunk.split('===');
        return { label: (parts[0]||'').trim(), content: (parts[1]||'').trim() };
      }).filter(function(t) { return t.label; });
      col.structJson({ tabs: tabs });
    }
  });

  col.collapsibleHeader = ko.pureComputed({
    read: function() { return (col.structJson()||{}).header || ''; },
    write: function(v) { var s = col.structJson()||{}; s.header = v; col.structJson(s); }
  });
  col.collapsibleContent = ko.pureComputed({
    read: function() { return (col.structJson()||{}).content || ''; },
    write: function(v) { var s = col.structJson()||{}; s.content = v; col.structJson(s); }
  });
  col.collapsibleExpanded = ko.pureComputed({
    read: function() { return !!(col.structJson()||{}).expanded; },
    write: function(v) { var s = col.structJson()||{}; s.expanded = !!v; col.structJson(s); }
  });

  return col;

}
   
function buildRow(rowData) {
  var layoutDef = layoutByCode(rowData.layout);

  var row = { rowSeq: rowData.rowSeq, layout: ko.observable(rowData.layout),
    bgColor: ko.observable(rowData.bgColor || ''), bgImage: ko.observable(rowData.bgImage || ''),
    cols: ko.observableArray([]) };

  row.layoutLabel = ko.computed(function() { return layoutByCode(row.layout()).label; });

  var segs = layoutDef.segments;

  (rowData.cols||[]).forEach(function(c, idx) { row.cols.push(buildCol(c, segs, idx)); });

  return row;
}
   
var viewModel = {
  pageTitle: ko.observable(PGDSN_DATA.descr || PGDSN_DATA.designId),
  lastUpdDttm: ko.observable(PGDSN_DATA.lastUpdDttm),
  rows: ko.observableArray((PGDSN_DATA.rows||[]).map(buildRow)),
  layoutOptions: LAYOUT_OPTIONS,
  contentTypeOptions: CONTENT_TYPE_OPTIONS,
  componentOptions: COMPONENT_OPTIONS,
  showAddRowPanel: ko.observable(false),
  showColEditor: ko.observable(false),
  editingCol: ko.observable(null),
  saving: ko.observable(false)
};
   
viewModel.openAddRowPanel = function() { viewModel.showColEditor(false); viewModel.showAddRowPanel(true); };

viewModel.closeAddRowPanel = function() { viewModel.showAddRowPanel(false); };

viewModel.selectLayout = function(layoutDef) {
  var maxSeq = 0;
  viewModel.rows().forEach(function(r) { if (r.rowSeq > maxSeq) maxSeq = r.rowSeq; });
  var newRowData = { rowSeq: maxSeq + 10, layout: layoutDef.code, bgColor:'', bgImage:'',
    cols: layoutDef.segments.map(function(pct, i) { return { colSeq: i+1, contentType:'TEXT', textValue:'New content' }; }) };
  viewModel.rows.push(buildRow(newRowData));
  viewModel.closeAddRowPanel();
};

viewModel.deleteRow = function(row) { if (confirm('Delete this row?')) { viewModel.rows.remove(row); } };

viewModel.selectCell = function(row, col) {
  viewModel.editingCol(col);
  viewModel.showAddRowPanel(false);
  viewModel.showColEditor(true);
};

viewModel.closeColEditor = function() { viewModel.showColEditor(false); viewModel.editingCol(null); };

viewModel.componentHasOptions = function(col) {
  if (!col) return false;
  var def = COMPONENT_OPTIONS.find(function(c) { return c.tag === col.componentTag(); });
  return !!(def && def.hasOptions);
};

viewModel.applyComponentDefaults = function(col) {
  var def = COMPONENT_OPTIONS.find(function(c) { return c.tag === col.componentTag(); });
  if (!def) return;
  col.componentProps(JSON.parse(JSON.stringify(def.defaultProps || {})));
  if (def.hasOptions) {
    col.componentOptions(JSON.parse(JSON.stringify(def.defaultOptions || { items: [] })));
  }
};

viewModel.onComponentTagChanged = function(col) { viewModel.applyComponentDefaults(col); };

viewModel.openSettings = function() { var v = prompt('Page title:', viewModel.pageTitle()); if (v !== null) viewModel.pageTitle(v); };

viewModel.togglePreview = function() {
  var url = window.location.pathname.replace('IScript_VPOrchestrator','IScript_JETLandingPage') + '?design=' + PGDSN_DATA.designId;
  window.open(url, '_blank');
};

viewModel.closeDesigner = function() { if (confirm('Leave designer? Unsaved changes will be lost.')) { window.close(); } };

viewModel.saveDesign = function() {
  viewModel.saving(true);
  var payload = { 
	designId: PGDSN_DATA.designId, 
	csrf: PGDSN_CSRF, 
	lastUpdDttm: viewModel.lastUpdDttm(), 
	descr: viewModel.pageTitle(),
    rows: viewModel.rows().map(function(r) { 
		return { 
			rowSeq: r.rowSeq, 
			layout: r.layout(), 
			bgColor: r.bgColor(), 
			bgImage: r.bgImage(),
			cols: r.cols().map(function(c) { 
				return { 
					colSeq: c.colSeq, 
					contentType: c.contentType(), 
					textValue: c.textValue(), 
					imageUrl: c.imageUrl(), 
					linkUrl: c.linkUrl(), 
					linkLabel: c.linkLabel(), 
					componentTag: c.componentTag(), 
					componentProps: c.componentProps(), 
					componentOptions: c.componentOptions(), 
					active: c.active(), 
					altText: c.altText(), 
					widgetClassPath: c.widgetClassPath(), 
					widgetMethod: c.widgetMethod(), 
					widgetProps: c.widgetProps(),
					structJson: c.structJson()
				}; 
			}) 
		}; 
	}) 
  };
  fetch(PGDSN_SAVE_URL, { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify(payload) })
    .then(function(resp) { return resp.json(); })
    .then(function(data) {
      viewModel.saving(false);
      if (data.status === 'ok') { viewModel.lastUpdDttm(data.lastUpdDttm); alert('Saved.'); }
      else if (data.status === 'conflict') { alert('This design was changed by someone else. Reload before saving.'); }
      else { alert('Save failed: ' + (data.message || 'Unknown error')); }
    })
    .catch(function(err) { viewModel.saving(false); alert('Save failed: ' + err); });
};

viewModel.onContentTypeChanged = function(col) {
  if (col.contentType() === 'COMPONENT' && (!col.componentTag() || Object.keys(col.componentProps()||{}).length === 0)) {
    if (!col.componentTag()) { col.componentTag(COMPONENT_OPTIONS[0].tag); }
    viewModel.applyComponentDefaults(col);
  }
};

ko.applyBindings(viewModel, document.getElementById('designerRoot'));

