class ComponentRegistry
   method ComponentRegistry();
   method IsSupported(&tag As string) Returns boolean;
   method GetAllTags() Returns array of string;
   method GetLabel(&tag As string) Returns string;
   method GetRequireModule(&tag As string) Returns string;
   method GetDefaultProps(&tag As string) Returns string;
   method GetPropNames(&tag As string) Returns array of string;
   method GetPropType(&tag As string, &propName As string) Returns string;
   method GetAllAsJson() Returns string;
   method GetAllRequireModules() Returns array of string;
   method GetDefaultOptions(&tag As string) Returns string;
   method GetHasOptions(&tag As string) Returns boolean;

end-class;

method ComponentRegistry
end-method;

method IsSupported
   /+ &tag as String +/
   /+ Returns Boolean +/
   Local array of string &tags = %This.GetAllTags();
   Local integer &i;
   For &i = 1 To &tags.Len
      If &tags [&i] = &tag Then
         Return True;
      End-If;
   End-For;
   Return False;
end-method;

/* THE ONE LIST - add a new tag here, then fill in its four lookups below */
method GetAllTags
   /+ Returns Array of String +/
   Local array of string &tags = CreateArrayRept("", 0);
   &tags.Push("oj-label");
   &tags.Push("oj-button");
   &tags.Push("oj-input-text");
   &tags.Push("oj-input-number");
   &tags.Push("oj-input-date");
   &tags.Push("oj-input-time");
   &tags.Push("oj-highlight-text");

   &tags.Push("oj-avatar");
   &tags.Push("oj-switch");
   &tags.Push("oj-slider");
   &tags.Push("oj-progress-bar");
   &tags.Push("oj-progress-circle");

   /* Options-Based Components */
   &tags.Push("oj-radioset");
   &tags.Push("oj-checkboxset");
   &tags.Push("oj-select-single");

   /* Gauges */
   &tags.Push("oj-led-gauge");
   &tags.Push("oj-rating-gauge");
   &tags.Push("oj-status-meter-gauge");

   Return &tags;
end-method;

method GetLabel
   /+ &tag as String +/
   /+ Returns String +/
   Evaluate &tag
   When "oj-label"
      Return "Label";
   When "oj-button"
      Return "Button";
   When "oj-input-text"
      Return "Text Input";
   When "oj-input-number"
      Return "Number Input";
   When "oj-input-date"
      Return "Date Input";
   When "oj-input-time"
      Return "Time Input";
   When "oj-highlight-text"
      Return "Highlighted Text";

   When "oj-progress-bar"
      Return "Progress Bar";
   When "oj-progress-circle"
      Return "Progress Circle";
   When "oj-avatar"
      Return "Avatar";
   When "oj-switch"
      Return "Switch (Toggle)";
   When "oj-slider"
      Return "Slider";

      /* Options-Based Components */
   When "oj-radioset"
      Return "Radio Set";
   When "oj-checkboxset"
      Return "Checkbox Set";
   When "oj-select-single"
      Return "Select Single";

      /* Gauges */
   When "oj-led-gauge"
      Return "LED Gauge";
   When "oj-rating-gauge"
      Return "Rating Gauge";
   When "oj-status-meter-gauge"
      Return "Status Meter Gauge";

   When-Other
      Return &tag;
   End-Evaluate;
end-method;

method GetRequireModule
   /+ &tag as String +/
   /+ Returns String +/
   Evaluate &tag
   When "oj-label"
      Return "ojs/ojlabel";
   When "oj-button"
      Return "ojs/ojbutton";
   When "oj-input-text"
      Return "ojs/ojinputtext";
   When "oj-input-number"
      Return "ojs/ojinputnumber";
   When "oj-input-date"
      Return "ojs/ojdatetimepicker";
   When "oj-input-time"
      Return "ojs/ojdatetimepicker";
   When "oj-highlight-text"
      Return "ojs/ojhighlighttext";

   When "oj-progress-bar"
      Return "ojs/ojprogress-bar";
   When "oj-progress-circle"
      Return "ojs/ojprogress-circle";
   When "oj-avatar"
      Return "ojs/ojavatar";
   When "oj-switch"
      Return "ojs/ojswitch";
   When "oj-slider"
      Return "ojs/ojslider";

      /* Options-Based Components */
   When "oj-radioset"
      Return "ojs/ojradioset";
   When "oj-checkboxset"
      Return "ojs/ojcheckboxset";
   When "oj-select-single"
      Return "ojs/ojselectsingle";

      /* Gauges */
   When "oj-led-gauge"
      Return "ojs/ojgauge";
   When "oj-rating-gauge"
      Return "ojs/ojgauge";
   When "oj-status-meter-gauge"
      Return "ojs/ojgauge";

   When-Other
      Return "";
   End-Evaluate;
end-method;

method GetDefaultProps
   /+ &tag as String +/
   /+ Returns String +/
   Evaluate &tag
   When "oj-label"
      Return "{""labelHint"":""Field Label""}";
   When "oj-button"
      Return "{""label"":""Click Me"",""chroming"":""solid""}";
   When "oj-input-text"
      Return "{""placeholder"":""""}";
   When "oj-input-number"
      Return "{""placeholder"":"""",""min"":0,""max"":100}";
   When "oj-input-date"
      Return "{""value"":""""}";
   When "oj-input-time"
      Return "{""value"":""""}";
   When "oj-highlight-text"
      Return "{""text"":""The quick brown fox"",""matchText"":""quick""}";

   When "oj-progress-bar"
      Return "{""value"":50,""max"":100}";
   When "oj-progress-circle"
      Return "{""value"":50,""max"":100}";
   When "oj-avatar"
      Return "{""initials"":""AB""}";
   When "oj-switch"
      Return "{""value"":true}";
   When "oj-slider"
      Return "{""value"":50,""min"":0,""max"":100}";

      /* Options-Based Components 
   When "oj-radioset"
      Return "ojs/ojradioset";
   When "oj-checkboxset"
      Return "ojs/ojcheckboxset";
   When "oj-select-single"
      Return "ojs/ojselectsingle";
      */

      /* Gauges */
   When "oj-led-gauge"
      Return "{""value"":50,""min"":0,""max"":100,""type"":""circle"",""color"":""#008000""}";
   When "oj-rating-gauge"
      Return "{""value"":3,""min"":0,""max"":5}";
   When "oj-status-meter-gauge"
      Return "{""value"":50,""min"":0,""max"":100}";

   When-Other
      Return "{}";
   End-Evaluate;
end-method;

method GetPropNames
   /+ &tag as String +/
   /+ Returns Array of String +/
   Local array of string &names = CreateArrayRept("", 0);
   Evaluate &tag
   When "oj-label"
      &names.Push("labelHint");
   When "oj-button"
      &names.Push("label");
      &names.Push("chroming");
   When "oj-input-text"
      &names.Push("placeholder");
   When "oj-input-number"
      &names.Push("placeholder");
      &names.Push("min");
      &names.Push("max");
   When "oj-input-date"
      &names.Push("value");
      &names.Push("min");
      &names.Push("max");
   When "oj-input-time"
      &names.Push("value");
      &names.Push("min");
      &names.Push("max");
   When "oj-highlight-text"
      &names.Push("text");
      &names.Push("matchText");

   When "oj-progress-bar"
      &names.Push("value");
      &names.Push("max");
   When "oj-progress-circle"
      &names.Push("value");
      &names.Push("max");
   When "oj-avatar"
      &names.Push("initials");
      &names.Push("src");
   When "oj-switch"
      &names.Push("value");
   When "oj-slider"
      &names.Push("value");
      &names.Push("min");
      &names.Push("max");

      /* Options-Based Components 
   When "oj-radioset"
      Return "ojs/ojradioset";
   When "oj-checkboxset"
      Return "ojs/ojcheckboxset";
   When "oj-select-single"
      Return "ojs/ojselectsingle";
      */

      /* Gauges */
   When "oj-led-gauge"
      &names.Push("value");
      &names.Push("min");
      &names.Push("max");
      &names.Push("type");
      &names.Push("color");
   When "oj-rating-gauge"
      &names.Push("value");
      &names.Push("min");
      &names.Push("max");
   When "oj-status-meter-gauge"
      &names.Push("value");
      &names.Push("min");
      &names.Push("max");
      &names.Push("orientation");
      &names.Push("color");

   When-Other
   End-Evaluate;
   Return &names;
end-method;

method GetPropType
   /+ &tag as String, +/
   /+ &propName as String +/
   /+ Returns String +/
   Evaluate &tag | "|" | &propName
   When "oj-label|labelHint"
      Return "STRING";
   When "oj-button|label"
      Return "STRING";
   When "oj-button|chroming"
      Return "STRING";
   When "oj-input-text|placeholder"
      Return "STRING";
   When "oj-input-number|placeholder"
      Return "STRING";
   When "oj-input-number|min"
      Return "NUMBER";
   When "oj-input-number|max"
      Return "NUMBER";
   When "oj-input-date|value"
      Return "STRING";
   When "oj-input-date|min"
      Return "STRING";
   When "oj-input-date|max"
      Return "STRING";
   When "oj-input-time|value"
      Return "STRING";
   When "oj-input-time|min"
      Return "STRING";
   When "oj-input-time|max"
      Return "STRING";
   When "oj-highlight-text|text"
      Return "STRING";
   When "oj-highlight-text|matchText"
      Return "STRING";

   When "oj-progress-bar|value"
      Return "NUMBER";
   When "oj-progress-bar|max"
      Return "NUMBER";

   When "oj-progress-circle|value"
      Return "NUMBER";
   When "oj-progress-circle|max"
      Return "NUMBER";

   When "oj-avatar|initials"
      Return "STRING";
   When "oj-avatar|src"
      Return "STRING";

   When "oj-switch|value"
      Return "BOOLEAN";

   When "oj-slider|value"
      Return "NUMBER";
   When "oj-slider|min"
      Return "NUMBER";
   When "oj-slider|max"
      Return "NUMBER";

      /* Options-Based Components 
   When "oj-radioset"
      Return "ojs/ojradioset";
   When "oj-checkboxset"
      Return "ojs/ojcheckboxset";
   When "oj-select-single"
      Return "ojs/ojselectsingle";
      */

      /* Gauges */
   When "oj-led-gauge|value"
      Return "NUMBER";
   When "oj-led-gauge|min"
      Return "NUMBER";
   When "oj-led-gauge|max"
      Return "NUMBER";
   When "oj-led-gauge|type"
      Return "STRING";
   When "oj-led-gauge|color"
      Return "STRING";

   When "oj-rating-gauge|value"
      Return "NUMBER";
   When "oj-rating-gauge|min"
      Return "NUMBER";
   When "oj-rating-gauge|max"
      Return "NUMBER";

   When "oj-status-meter-gauge|value"
      Return "NUMBER";
   When "oj-status-meter-gauge|min"
      Return "NUMBER";
   When "oj-status-meter-gauge|max"
      Return "NUMBER";
   When "oj-status-meter-gauge|orientation"
      Return "STRING";
   When "oj-status-meter-gauge|color"
      Return "STRING";

   When-Other
      Return "STRING";
   End-Evaluate;
end-method;

method GetAllAsJson
   /+ Returns String +/
   Local array of string &tags = %This.GetAllTags();
   Local string &j;
   Local integer &i;
   &j = "[";
   For &i = 1 To &tags.Len
      If &i > 1 Then
         &j = &j | ",";
      End-If;
      rem &j = &j | "{""tag"":""" | &tags [&i] | """,""label"":""" | %This.GetLabel(&tags [&i]) | """,""defaultProps"":" | %This.GetDefaultProps(&tags [&i]) | "}";
      Local string &hasOptStr;
      If %This.GetHasOptions(&tags [&i]) Then
         &hasOptStr = "true";
      Else
         &hasOptStr = "false";
      End-If;
      &j = &j | "{""tag"":""" | &tags [&i] | """,""label"":""" | %This.GetLabel(&tags [&i]) | """,""defaultProps"":" | %This.GetDefaultProps(&tags [&i]) | ",""hasOptions"":" | &hasOptStr | "}";

   End-For;
   &j = &j | "]";
   Return &j;
end-method;

method GetAllRequireModules
   /+ Returns Array of String +/
   Local array of string &tags = %This.GetAllTags();
   Local array of string &mods = CreateArrayRept("", 0);
   Local integer &i;
   Local string &m;
   For &i = 1 To &tags.Len
      &m = %This.GetRequireModule(&tags [&i]);
      If &m <> "" Then
         &mods.Push(&m);
      End-If;
   End-For;
   Return &mods;
end-method;

method GetHasOptions
   /+ &tag as String +/
   /+ Returns Boolean +/
   Evaluate &tag
   When "oj-checkboxset"
   When "oj-radioset"
   When "oj-select-single"
      Return True;
   When-Other
      Return False;
   End-Evaluate;
end-method;

method GetDefaultOptions
   /+ &tag as String +/
   /+ Returns String +/
   Return "{""items"":[{""value"":""opt1"",""label"":""Option 1""},{""value"":""opt2"",""label"":""Option 2""}]}";
end-method;

class LayoutEngine
   method LayoutEngine();
   method GetPercentages(&layoutCode As string) Returns array of number;
   method GetLabel(&layoutCode As string) Returns string;
   method GetAllCodes() Returns array of string;
   method GetAllLayoutsAsJson() Returns string;
end-class;

method LayoutEngine
end-method;

method GetPercentages
   /+ &layoutCode as String +/
   /+ Returns Array of Number +/
   Local array of number &pcts = CreateArrayRept(0, 0);

   Evaluate &layoutCode
   When "1COL"
      &pcts.Push(100);
   When "2COL_5050"
      &pcts.Push(50);
      &pcts.Push(50);
   When "2COL_7030"
      &pcts.Push(70);
      &pcts.Push(30);
   When "2COL_3070"
      &pcts.Push(30);
      &pcts.Push(70);
   When "2COL_6040"
      &pcts.Push(60);
      &pcts.Push(40);
   When "2COL_4060"
      &pcts.Push(40);
      &pcts.Push(60);
   When "3COL_333333"
      &pcts.Push(33.34);
      &pcts.Push(33.33);
      &pcts.Push(33.33);
   When "3COL_502525"
      &pcts.Push(50);
      &pcts.Push(25);
      &pcts.Push(25);
   When "3COL_255025"
      &pcts.Push(25);
      &pcts.Push(50);
      &pcts.Push(25);
   When "3COL_252550"
      &pcts.Push(25);
      &pcts.Push(25);
      &pcts.Push(50);
   When-Other
      &pcts.Push(100);
   End-Evaluate;

   Return &pcts;
end-method;

method GetLabel
   /+ &layoutCode as String +/
   /+ Returns String +/
   Local string &label;

   Evaluate &layoutCode
   When "1COL"
      &label = "100%";
   When "2COL_5050"
      &label = "50% / 50%";
   When "2COL_7030"
      &label = "70% / 30%";
   When "2COL_3070"
      &label = "30% / 70%";
   When "2COL_6040"
      &label = "60% / 40%";
   When "2COL_4060"
      &label = "40% / 60%";
   When "3COL_333333"
      &label = "33% / 33% / 33%";
   When "3COL_502525"
      &label = "50% / 25% / 25%";
   When "3COL_255025"
      &label = "25% / 50% / 25%";
   When "3COL_252550"
      &label = "25% / 25% / 50%";
   When-Other
      &label = &layoutCode;
   End-Evaluate;

   Return &label;
end-method;

method GetAllCodes
   /+ Returns Array of String +/
   Local array of string &codes = CreateArrayRept("", 0);
   &codes.Push("1COL");
   &codes.Push("2COL_5050");
   &codes.Push("2COL_7030");
   &codes.Push("2COL_3070");
   &codes.Push("2COL_6040");
   &codes.Push("2COL_4060");
   &codes.Push("3COL_333333");
   &codes.Push("3COL_502525");
   &codes.Push("3COL_255025");
   &codes.Push("3COL_252550");
   Return &codes;
end-method;

method GetAllLayoutsAsJson
   /+ Returns String +/
   Local array of string &codes = %This.GetAllCodes();
   Local array of number &segs;
   Local string &json, &code;
   Local integer &i, &s;

   &json = "[";
   For &i = 1 To &codes.Len
      &code = &codes [&i];
      If &i > 1 Then
         &json = &json | ",";
      End-If;
      &json = &json | "{""code"":""" | &code | """,""label"":""" | %This.GetLabel(&code) | """,""segments"":[";
      &segs = %This.GetPercentages(&code);
      For &s = 1 To &segs.Len
         If &s > 1 Then
            &json = &json | ",";
         End-If;
         &json = &json | &segs [&s];
      End-For;
      &json = &json | "]}";
   End-For;
   &json = &json | "]";
   Return &json;
end-method;

import OU_JET_PACK:Utils:JsonUtil;

class PageCol
   method PageCol();
   property number ColSeq;
   property string ContentType;
   property string TextValue;
   property string ImageUrl;
   property string LinkUrl;
   property string LinkLabel;
   property string ComponentTag;
   property string ComponentProps;
   property string ComponentOptions;
   property boolean Active;
   property string AltText;
   property string WidgetClassPath;
   property string WidgetMethod;
   property string WidgetProps;
   property string StructJson;
   method ToJson() Returns string;
   method FromJsonObject(&jo As JsonObject);
end-class;

method PageCol
   %This.ContentType = "TEXT";
   %This.TextValue = "";
   %This.ImageUrl = "";
   %This.LinkUrl = "";
   %This.LinkLabel = "";
   %This.ComponentTag = "";
   %This.ComponentProps = "{}";
   %This.ComponentOptions = "{""items"":[]}";
   %This.Active = True;
   %This.AltText = "";
   %This.WidgetClassPath = "";
   %This.WidgetMethod = "Render";
   %This.WidgetProps = "{}";
   %This.StructJson = "{}";
end-method;

method ToJson
   /+ Returns String +/
   Local OU_JET_PACK:Utils:JsonUtil &u = create OU_JET_PACK:Utils:JsonUtil();
   Local string &j, &propsJson, &optionsJson, &widgetPropsJson, &activeStr;

   If %This.ComponentProps = "" Then
      &propsJson = "{}";
   Else
      &propsJson = %This.ComponentProps;
   End-If;

   If %This.ComponentOptions = "" Then
      &optionsJson = "{""items"":[]}";
   Else
      &optionsJson = %This.ComponentOptions;
   End-If;

   If %This.WidgetProps = "" Then
      &widgetPropsJson = "{}";
   Else
      &widgetPropsJson = %This.WidgetProps;
   End-If;

   If %This.Active Then
      &activeStr = "true";
   Else
      &activeStr = "false";
   End-If;

   &j = "{""colSeq"":" | %This.ColSeq | ",";
   &j = &j | """contentType"":""" | &u.EscapeJson(%This.ContentType) | """,";
   &j = &j | """textValue"":""" | &u.EscapeJson(%This.TextValue) | """,";
   &j = &j | """imageUrl"":""" | &u.EscapeJson(%This.ImageUrl) | """,";
   &j = &j | """linkUrl"":""" | &u.EscapeJson(%This.LinkUrl) | """,";
   &j = &j | """linkLabel"":""" | &u.EscapeJson(%This.LinkLabel) | """,";
   &j = &j | """componentTag"":""" | &u.EscapeJson(%This.ComponentTag) | """,";
   &j = &j | """componentProps"":" | &propsJson | ",";
   &j = &j | """componentOptions"":" | &optionsJson | ",";
   &j = &j | """active"":" | &activeStr | ",";
   &j = &j | """altText"":""" | &u.EscapeJson(%This.AltText) | """,";
   &j = &j | """widgetClassPath"":""" | &u.EscapeJson(%This.WidgetClassPath) | """,";
   &j = &j | """widgetMethod"":""" | &u.EscapeJson(%This.WidgetMethod) | """,";

   Local string &structJsonOut;
   If %This.StructJson = "" Then
      &structJsonOut = "{}";
   Else
      &structJsonOut = %This.StructJson;
   End-If;

   &j = &j | """widgetProps"":" | &widgetPropsJson | ",";
   &j = &j | """structJson"":" | &structJsonOut | "}";

   Return &j;
end-method;

method FromJsonObject
   /+ &jo as JsonObject +/
   %This.ColSeq = &jo.GetNumber("colSeq");
   %This.ContentType = &jo.GetString("contentType");
   %This.TextValue = &jo.GetString("textValue");
   %This.ImageUrl = &jo.GetString("imageUrl");
   %This.LinkUrl = &jo.GetString("linkUrl");
   %This.LinkLabel = &jo.GetString("linkLabel");
   %This.ComponentTag = &jo.GetString("componentTag");
   %This.AltText = &jo.GetString("altText");
   %This.WidgetClassPath = &jo.GetString("widgetClassPath");
   %This.WidgetMethod = &jo.GetString("widgetMethod");

   try
      %This.Active = &jo.GetBoolean("active");
   catch Exception &e
      %This.Active = True;
   end-try;

   Local JsonObject &propsObj = &jo.GetJsonObject("componentProps");
   If &propsObj <> Null Then
      %This.ComponentProps = &propsObj.ToString();
   Else
      %This.ComponentProps = "{}";
   End-If;

   Local JsonObject &optionsObj = &jo.GetJsonObject("componentOptions");
   If &optionsObj <> Null Then
      %This.ComponentOptions = &optionsObj.ToString();
   Else
      %This.ComponentOptions = "{""items"":[]}";
   End-If;

   Local JsonObject &widgetPropsObj = &jo.GetJsonObject("widgetProps");
   If &widgetPropsObj <> Null Then
      %This.WidgetProps = &widgetPropsObj.ToString();
   Else
      %This.WidgetProps = "{}";
   End-If;

   Local JsonObject &structObj = &jo.GetJsonObject("structJson");
   If &structObj <> Null Then
      %This.StructJson = &structObj.ToString();
   Else
      %This.StructJson = "{}";
   End-If;

end-method;

import OU_JET_PACK:Utils:JsonUtil;
import OU_JET_PACK:Model:PageRow;

class PageDesign
   method PageDesign(&id As string);
   property string PageId;
   property string Descr;
   property string LastUpdDttm;
   property string PgdsnStatus;
   property boolean IsNew;
   property array of OU_JET_PACK:Model:PageRow Rows;
   method ToJson() Returns string;
   method FromJsonBody(&body As string) Returns string;
private
   instance OU_JET_PACK:Model:PageRow &REF_Row;
end-class;

method PageDesign
   /+ &id as String +/
   %This.PageId = &id;
   %This.Descr = "";
   %This.LastUpdDttm = "";
   %This.PgdsnStatus = "A";
   %This.IsNew = True;
   %This.Rows = CreateArrayRept(&REF_Row, 0);
end-method;

method ToJson
   /+ Returns String +/
   Local OU_JET_PACK:Utils:JsonUtil &u = create OU_JET_PACK:Utils:JsonUtil();
   Local string &j, &isNewStr;
   Local integer &i;

   If %This.IsNew Then
      &isNewStr = "true";
   Else
      &isNewStr = "false";
   End-If;

   &j = "{""designId"":""" | &u.EscapeJson(%This.PageId) | """,";
   &j = &j | """descr"":""" | &u.EscapeJson(%This.Descr) | """,";
   &j = &j | """lastUpdDttm"":""" | %This.LastUpdDttm | """,";
   &j = &j | """isNew"":" | &isNewStr | ",";
   &j = &j | """rows"":[";
   For &i = 1 To %This.Rows.Len
      If &i > 1 Then
         &j = &j | ",";
      End-If;
      &j = &j | %This.Rows [&i].ToJson();
   End-For;
   &j = &j | "]}";

   Return &j;
end-method;

method FromJsonBody
   /+ &body as String +/
   /+ Returns String +/
   Local JsonParser &jp = CreateJsonParser();
   Local JsonObject &jo, &rowObj;
   Local JsonArray &rowsArr;
   Local OU_JET_PACK:Model:PageRow &row;
   Local integer &r;
   Local string &csrf;

   If Not &jp.Parse(&body) Then
      Return "";
   End-If;
   &jo = &jp.GetRootObject();

   %This.Descr = &jo.GetString("descr");
   %This.LastUpdDttm = &jo.GetString("lastUpdDttm");
   &csrf = &jo.GetString("csrf");

   %This.Rows = CreateArrayRept(&REF_Row, 0);
   &rowsArr = &jo.GetJsonArray("rows");
   For &r = 1 To &rowsArr.Length()
      &rowObj = &rowsArr.GetJsonObject(&r);
      &row = create OU_JET_PACK:Model:PageRow();
      &row.FromJsonObject(&rowObj);
      %This.Rows.Push(&row);
   End-For;

   Return &csrf;
end-method;

import OU_JET_PACK:Utils:JsonUtil;
import OU_JET_PACK:Model:PageCol;

class PageRow
   method PageRow();
   property number RowSeq;
   property string Layout;
   property string BgColor;
   property string BgImage;
   property array of OU_JET_PACK:Model:PageCol Cols;
   method ToJson() Returns string;
   method FromJsonObject(&jo As JsonObject);
private
   instance OU_JET_PACK:Model:PageCol &REF_Col;
end-class;

method PageRow
   %This.Layout = "1COL";
   %This.BgColor = "";
   %This.BgImage = "";
   %This.Cols = CreateArrayRept(&REF_Col, 0);
end-method;

method ToJson
   /+ Returns String +/
   Local OU_JET_PACK:Utils:JsonUtil &u = create OU_JET_PACK:Utils:JsonUtil();
   Local string &j;
   Local integer &i;

   &j = "{""rowSeq"":" | %This.RowSeq | ",";
   &j = &j | """layout"":""" | &u.EscapeJson(%This.Layout) | """,";
   &j = &j | """bgColor"":""" | &u.EscapeJson(%This.BgColor) | """,";
   &j = &j | """bgImage"":""" | &u.EscapeJson(%This.BgImage) | """,";
   &j = &j | """cols"":[";
   For &i = 1 To %This.Cols.Len
      If &i > 1 Then
         &j = &j | ",";
      End-If;
      &j = &j | %This.Cols [&i].ToJson();
   End-For;
   &j = &j | "]}";
   Return &j;
end-method;

method FromJsonObject
   /+ &jo as JsonObject +/
   Local JsonArray &colsArr;
   Local JsonObject &colObj;
   Local OU_JET_PACK:Model:PageCol &col;
   Local integer &c;

   %This.RowSeq = &jo.GetNumber("rowSeq");
   %This.Layout = &jo.GetString("layout");
   %This.BgColor = &jo.GetString("bgColor");
   %This.BgImage = &jo.GetString("bgImage");
   %This.Cols = CreateArrayRept(&REF_Col, 0);

   &colsArr = &jo.GetJsonArray("cols");
   For &c = 1 To &colsArr.Length()
      &colObj = &colsArr.GetJsonObject(&c);
      &col = create OU_JET_PACK:Model:PageCol();
      &col.FromJsonObject(&colObj);
      %This.Cols.Push(&col);
   End-For;
end-method;

