import OU_JET_PACK:Model:PageDesign;
import OU_JET_PACK:Model:PageRow;
import OU_JET_PACK:Model:PageCol;
import OU_JET_PACK:Layout:LayoutEngine;
import OU_JET_PACK:Layout:ComponentRegistry;

class PageRenderer
   method PageRenderer();
   method Render(&design As OU_JET_PACK:Model:PageDesign) Returns string;
   method NeedsStructuredWidgetAssets(&design As OU_JET_PACK:Model:PageDesign) Returns boolean;
end-class;

method PageRenderer
end-method;

method Render
   /+ &design as OU_JET_PACK:Model:PageDesign +/
   /+ Returns String +/
   Local OU_JET_PACK:Layout:LayoutEngine &engine = create OU_JET_PACK:Layout:LayoutEngine();
   Local string &out, &style;
   Local integer &r, &c;
   Local array of number &pcts;
   Local OU_JET_PACK:Model:PageRow &row;
   Local OU_JET_PACK:Model:PageCol &col;
   Local number &pct;

   &out = "";
   For &r = 1 To &design.Rows.Len
      &row = &design.Rows [&r];
      &pcts = &engine.GetPercentages(&row.Layout);

      &style = "";
      If &row.BgColor <> "" Then
         &style = &style | "background-color:" | &row.BgColor | ";";
      End-If;
      If &row.BgImage <> "" Then
         &style = &style | "background-image:url(" | &row.BgImage | ");background-size:cover;background-position:center;";
      End-If;

      &out = &out | "<div class='oj-flex jet-pg-row' style='" | &style | "'>";

      For &c = 1 To &row.Cols.Len
         &col = &row.Cols [&c];
         If &c <= &pcts.Len Then
            &pct = &pcts [&c];
         Else
            &pct = 100 / &row.Cols.Len;
         End-If;

         &out = &out | "<div class='oj-flex-item jet-pg-col' style='flex-basis:" | &pct | "%;'>";

         If &col.Active Then
            Evaluate &col.ContentType
            When "TEXT"
               &out = &out | "<p>" | &col.TextValue | "</p>";
               Break;
            When "HTML"
               &out = &out | &col.TextValue;
               Break;
            When "IMAGE"
               &out = &out | "<img class='jet-pg-img' src='" | &col.ImageUrl | "'/>";
               Break;
            When "LINK"
               &out = &out | "<a class='oj-button jet-pg-link' href='" | &col.LinkUrl | "'>" | &col.LinkLabel | "</a>";
               Break;
            When "COMPONENT"
               If &col.ComponentTag <> "" Then
                  Local JsonParser &jp = CreateJsonParser();
                  Local JsonObject &propsObj;
                  Local integer &k;
                  Local string &propVal, &slotContent, &attrStr;

                  Local OU_JET_PACK:Layout:ComponentRegistry &registry = create OU_JET_PACK:Layout:ComponentRegistry();

                  If &registry.GetHasOptions(&col.ComponentTag) Then
                     Local JsonParser &jpo = CreateJsonParser();
                     Local JsonObject &optsRoot;
                     Local JsonArray &itemsArr;
                     Local JsonObject &itemObj;
                     Local integer &oi;
                     Local string &optVal, &optLabel, &optChildren;

                     &optChildren = "";

                     If &jpo.Parse(&col.ComponentOptions) Then
                        &optsRoot = &jpo.GetRootObject();
                        &itemsArr = &optsRoot.GetJsonArray("items");
                        For &oi = 1 To &itemsArr.Length()
                           &itemObj = &itemsArr.GetJsonObject(&oi);
                           &optVal = &itemObj.GetString("value");
                           &optLabel = &itemObj.GetString("label");
                           &optChildren = &optChildren | "<oj-option value='" | &optVal | "'>" | &optLabel | "</oj-option>";
                        End-For;
                     End-If;

                     &out = &out | "<" | &col.ComponentTag | ">" | &optChildren | "</" | &col.ComponentTag | ">";
                  Else

                     Local array of string &propNames = &registry.GetPropNames(&col.ComponentTag);

                     &slotContent = "";
                     &attrStr = "";

                     If &jp.Parse(&col.ComponentProps) Then
                        &propsObj = &jp.GetRootObject();

                        For &k = 1 To &propNames.Len


                           Local string &propType;
                           &propType = &registry.GetPropType(&col.ComponentTag, &propNames [&k]);

                           Evaluate &propType
                           When "NUMBER"
                              try
                                 &propVal = String(&propsObj.GetNumber(&propNames [&k]));
                              catch Exception &eN
                                 &propVal = "";
                              end-try;
                           When "BOOLEAN"
                              try
                                 If &propsObj.GetBoolean(&propNames [&k]) Then
                                    &propVal = "true";
                                 Else
                                    &propVal = "false";
                                 End-If;
                              catch Exception &eB
                                 &propVal = "";
                              end-try;
                           When-Other
                              try
                                 &propVal = &propsObj.GetString(&propNames [&k]);
                              catch Exception &eS
                                 &propVal = "";
                              end-try;
                           End-Evaluate;

                           If &propVal <> "" Then
                              If &col.ComponentTag = "oj-button" And
                                    &propNames [&k] = "label" Then
                                 &slotContent = &propVal;
                              Else
                                 &attrStr = &attrStr | &propNames [&k] | "='" | &propVal | "' ";
                              End-If;
                           End-If;
                        End-For;
                     End-If;

                     &out = &out | "<" | &col.ComponentTag | " " | &attrStr | ">" | &slotContent | "</" | &col.ComponentTag | ">";
                  End-If;
               End-If;
               Break;
            When "WIDGET"
               If &col.WidgetClassPath <> "" Then
                  Local object &widgetObj;
                  Local string &methodName, &renderResult;

                  If &col.WidgetMethod = "" Then
                     &methodName = "Render";
                  Else
                     &methodName = &col.WidgetMethod;
                  End-If;

                  try
                     &widgetObj = CreateObject(&col.WidgetClassPath);
                     &renderResult = ObjectDoMethod(&widgetObj, &methodName, &col.WidgetProps);
                     &out = &out | &renderResult;
                  catch Exception &e4
                     &out = &out | "<!-- widget render failed -->";
                  end-try;
               End-If;
               Break;
            When "CARD_FLIP"
               Local JsonParser &jpf = CreateJsonParser();
               Local JsonObject &cardObj;
               Local string &frontHtml, &backHtml;
               &frontHtml = "";
               &backHtml = "";
               If &jpf.Parse(&col.StructJson) Then
                  &cardObj = &jpf.GetRootObject();
                  &frontHtml = &cardObj.GetString("front");
                  &backHtml = &cardObj.GetString("back");
               End-If;
               &out = &out | "<div class='jet-flipcard' onclick=""this.classList.toggle('flipped')"">";
               &out = &out | "<div class='jet-flipcard-inner'>";
               &out = &out | "<div class='jet-flipcard-front'>" | &frontHtml | "</div>";
               &out = &out | "<div class='jet-flipcard-back'>" | &backHtml | "</div>";
               &out = &out | "</div></div>";
               Break;
            When "TABS"
               Local JsonParser &jpt = CreateJsonParser();
               Local JsonObject &tabsRoot;
               Local JsonArray &tabsArr;
               Local JsonObject &tabObj;
               Local integer &ti;
               Local string &tabLabel, &tabContent, &headersHtml, &panelsHtml, &activeCls;

               &headersHtml = "";
               &panelsHtml = "";
               If &jpt.Parse(&col.StructJson) Then
                  &tabsRoot = &jpt.GetRootObject();
                  &tabsArr = &tabsRoot.GetJsonArray("tabs");
                  For &ti = 1 To &tabsArr.Length()
                     &tabObj = &tabsArr.GetJsonObject(&ti);
                     &tabLabel = &tabObj.GetString("label");
                     &tabContent = &tabObj.GetString("content");
                     If &ti = 1 Then
                        &activeCls = " active";
                     Else
                        &activeCls = "";
                     End-If;
                     &headersHtml = &headersHtml | "<button class='jet-tab-btn" | &activeCls | "' onclick=""jetTabSwitch(this," | (&ti - 1) | ")"">" | &tabLabel | "</button>";
                     &panelsHtml = &panelsHtml | "<div class='jet-tab-panel" | &activeCls | "'>" | &tabContent | "</div>";
                  End-For;
               End-If;
               &out = &out | "<div class='jet-tabs'>";
               &out = &out | "<div class='jet-tabs-headers'>" | &headersHtml | "</div>";
               &out = &out | "<div class='jet-tabs-panels'>" | &panelsHtml | "</div>";
               &out = &out | "</div>";
               Break;
            When "COLLAPSIBLE"
               Local JsonParser &jpc = CreateJsonParser();
               Local JsonObject &panelObj;
               Local string &headerHtml, &contentHtml, &expandedStr;
               Local boolean &expandedVal;
               &headerHtml = "Section";
               &contentHtml = "";
               &expandedStr = "false";
               If &jpc.Parse(&col.StructJson) Then
                  &panelObj = &jpc.GetRootObject();
                  If &panelObj.GetString("header") <> "" Then
                     &headerHtml = &panelObj.GetString("header");
                  End-If;
                  &contentHtml = &panelObj.GetString("content");
                  try
                     &expandedVal = &panelObj.GetBoolean("expanded");
                  catch Exception &e5
                     &expandedVal = False;
                  end-try;
                  If &expandedVal Then
                     &expandedStr = "true";
                  End-If;
               End-If;
               &out = &out | "<oj-collapsible expanded=""" | &expandedStr | """>";
               &out = &out | "<h3 slot='header'>" | &headerHtml | "</h3>";
               &out = &out | "<div>" | &contentHtml | "</div>";
               &out = &out | "</oj-collapsible>";
               Break;
            End-Evaluate;
         End-If;

         &out = &out | "</div>";
      End-For;

      &out = &out | "</div>";
   End-For;

   Return &out;
end-method;


method NeedsStructuredWidgetAssets
   /+ &design as OU_JET_PACK:Model:PageDesign +/
   /+ Returns Boolean +/
   Local integer &r, &c;
   For &r = 1 To &design.Rows.Len
      For &c = 1 To &design.Rows [&r].Cols.Len
         If &design.Rows [&r].Cols [&c].ContentType = "CARD_FLIP" Or
               &design.Rows [&r].Cols [&c].ContentType = "TABS" Then
            Return True;
         End-If;
      End-For;
   End-For;
   Return False;
end-method;

