class WidgetRegistry
   method WidgetRegistry();
   method IsSupported(&key As string) Returns boolean;
   method GetDefaultProps(&key As string) Returns string;
   method GetAllAsJson() Returns string;
end-class;

method WidgetRegistry
end-method;

method IsSupported
   /+ &key as String +/
   /+ Returns Boolean +/
   Evaluate &key
   When "WELCOME_BANNER"
   When "PENDING_APPROVALS"
      Return True;
   When-Other
      Return False;
   End-Evaluate;
end-method;

method GetDefaultProps
   /+ &key as String +/
   /+ Returns String +/
   Evaluate &key
   When "WELCOME_BANNER"
      Return "{}";
   When "PENDING_APPROVALS"
      Return "{""maxRows"":5}";
   When-Other
      Return "{}";
   End-Evaluate;
end-method;

method GetAllAsJson
   /+ Returns String +/
   Local string &j;
   &j = "[";
   &j = &j | "{""key"":""WELCOME_BANNER"",""label"":""Welcome Banner""},";
   &j = &j | "{""key"":""PENDING_APPROVALS"",""label"":""Pending Approvals List""}";
   &j = &j | "]";
   Return &j;
end-method;

